from typing import Optional

# A release heading. The date is optional: `## [Unreleased]` has none.
HEADING = re.compile(
    r"^## \[(?P<version>[^\]]+)\](?: - (?P<date>\d{4}-\d{2}-\d{2}))?\s*$"
)

# HTML comments, single-line or spanning several lines. Maintainer notes only.
COMMENT = re.compile(r"<!--.*?-->", re.DOTALL)

# Placeholder left where a comment was removed, so the line it sat on can be
# identified afterwards. NUL cannot appear in a Markdown changelog.
_MARK = "\x00"


@dataclass
class Release:
    version: str
    date: Optional[str]
    body: list = field(default_factory=list)


def strip_comments(text):
    """Remove HTML comments, and drop trailing whitespace a removed comment left behind."""
    text = COMMENT.sub(_MARK, text)
    lines = []
    for line in text.split("\n"):
        if _MARK in line:
            ends_with_comment = line.rstrip(" \t").endswith(_MARK)
            line = line.replace(_MARK, "")
            if ends_with_comment:
                line = line.rstrip(" \t")
        lines.append(line)
    return "\n".join(lines)


def parse_changelog(text):
    text = strip_comments(text.replace("\r\n", "\n").replace("\r", "\n"))
    releases = []
    current = None
    for line in text.split("\n"):
        if line.startswith("## "):
            match = HEADING.match(line)
            if match is None:
                raise ValueError(f"malformed release heading: {line!r}")
            current = Release(match.group("version"), match.group("date"))
            releases.append(current)
        elif current is not None:
            current.body.append(line)
    return releases


def _normalize_body(lines):
    """Collapse runs of blank lines to one, and trim leading and trailing blank lines."""
    out = []
    for line in lines:
        if line.strip() == "":
            if out and out[-1] == "":
                continue
            out.append("")
        else:
            out.append(line)
    while out and out[0] == "":
        out.pop(0)
    while out and out[-1] == "":
        out.pop()
    return "\n".join(out)


def render_release(text, version):
    for release in parse_changelog(text):
        if release.version == version:
            heading = f"# {release.version}"
            if release.date:
                heading += f" ({release.date})"
            body = _normalize_body(release.body)
            return f"{heading}\n\n{body}\n"
    raise LookupError(version)

